"""Literal public templates and version information for the command line interface."""
from pathlib import Path

VERSION = '1.17.0'
REVISION = 'e5ae56451b5cdb692a5f8fd7f914488e85b33721'
VERSION_FULL = VERSION + ' (' + REVISION + ')'


def data(name):
    path = str(Path(__file__).parent / 'data' / name)
    if hasattr(__loader__, 'get_data'):
        return __loader__.get_data(path)
    return Path(path).read_bytes()


def text(name):
