"""Doxyfile lexer, option table, validation and loss-aware serialization.

The grammar is line oriented. Lists and scalar strings deliberately have different
quoting rules, and update mode preserves expressions without evaluating them.
"""
import copy
import json
import os
import re
import sys
from pathlib import Path
from resources import text, VERSION_FULL

META = json.loads(text('options.json'))
for item in META.values():
    if 'enum' in item:
        item['enum'] = [x.strip() for x in item['enum']]
ASSIGNMENT = re.compile(r'^([A-Z_0-9]+)([ \t]*)=([^\n]*(?:\\\n[^\n]*)*)\n', re.M)


class ConfigError(Exception):
    pass


def quote(s):
    return '"' + s.replace('"', '\\"') + '"' if re.search(r'[\s,#"]', s) else s


def remove_comment(s):
    q = False
    i = 0
    while i < len(s):
        if s[i] == '\\' and i+1 < len(s):
            i += 2
            continue
        if s[i] == '"':
            q = not q
        if s[i] == '#' and not q:
            return s[:i]
        i += 1
    return s


def tokens(s):
    """Return values paired with whether the original list item was quoted."""
    out = []
    i = 0
    malformed = False
    while i < len(s):
        while i < len(s) and (s[i].isspace() or s[i] == ','):
            i += 1
        if i == len(s):
            break
        quoted = s[i] == '"'
        v = ''
        if quoted:
            i += 1
            closed = False
            while i < len(s):
                if s[i] == '"':
                    i += 1
                    closed = True
                    break
                if s[i] == '\\' and i+1 < len(s) and s[i+1] == '"':
                    v += '"'
                    i += 2
                else:
                    v += s[i]
                    i += 1
            if not closed or (i < len(s) and not s[i].isspace() and s[i] != ','):
                malformed = True
        else:
            while i < len(s) and not s[i].isspace() and s[i] != ',':
                if s[i] == '\\' and i+1 < len(s):
                    v += s[i:i+2]
                    i += 2
                elif s[i] == '"':
                    malformed = True
                    break
                else:
                    v += s[i]
                    i += 1
        if v:
            out.append((v, quoted))
    return out, malformed


def scalar(s):
    # Quotes may surround the whole string; unquoted scalar whitespace is significant.
    s = s.strip()
    if '"' not in s:
        return s, False
    if s.startswith('"') and s.endswith('"'):
        body = s[1:-1]
        if not re.search(r'(?<!\\)"', body):
            return body.replace('\\"', '"').strip(), False
    if s.startswith('"'):
        vals, _ = tokens(s)
        return ' '.join(v for v,q in vals).strip(), True
    return s.replace('"', '').strip(), True


def defaults():
    vals = {}
    for m in ASSIGNMENT.finditer(text('config-short.txt')):
        name, _, s = m.groups()
        s = s.replace('\\\n', ' ').strip()
        if META[name]['type'] == 'stringlist':
            vals[name] = tokens(s)[0]
        else:
            vals[name] = scalar(s)[0]
    return vals


DEFAULTS = defaults()
ORDER = list(DEFAULTS)

# Older settings accepted by the public interface, but no longer written.
OBSOLETE = set('''DETAILS_AT_TOP HTML_ALIGN_MEMBERS HTML_HEADER HTML_COLORSTYLE
SYMBOL_CACHE_SIZE COLS_IN_ALPHA_INDEX HTML_TIMESTAMP LATEX_TIMESTAMP
DOT_FONTNAME DOT_FONTSIZE CLASS_DIAGRAMS MSCGEN_PATH PERL_PATH
USE_WINDOWS_ENCODING MSCGEN_TOOLCHAIN SEARCH_INCLUDES LEGACY_PUBLIC_API
CLANG_ASSISTED_PARSING CLANG_OPTIONS CLANG_DATABASE_PATH
GENERATE_TREEVIEW HTML_DYNAMIC_MENUS EXT_LINKS_IN_WINDOW DOT_TRANSPARENT
FORMULA_TRANSPARENT HTML_COLORSTYLE_HUE HTML_COLORSTYLE_SAT HTML_COLORSTYLE_GAMMA
DOC_ABSTRACTION ALL_GRAPHICAL_HIERARCHY USER_COMMENTS SOURCE_TOOLTIPS
'''.split()) - set(META)


class Configuration:
    def __init__(self):
        self.values = copy.deepcopy(DEFAULTS)
        self.comments = {}
        self.trailing = ''
        self.seen = set()
        self.include_paths = []
        self.old = {}
        self.failed_warnings = False
        self.config_name = '-'

    def warning(self, message):
        sys.stderr.write('warning: ' + message + '\n')

    def parse_file(self, filename, depth=0):
        if depth > 10:
            raise ConfigError('error: maximum include depth (10) exceeded!\nExiting...\n')
        try:
            b = sys.stdin.buffer.read() if filename == '-' else Path(filename).read_bytes()
        except OSError:
            raise ConfigError("error: file '%s' not found or could not be opened\nExiting...\n" % filename)
        # The encoding tag applies to subsequent bytes. ASCII tags are safe to inspect first.
        enc = self.values.get('DOXYFILE_ENCODING', 'UTF-8') or 'UTF-8'
        em = re.search(rb'(?m)^\s*DOXYFILE_ENCODING\s*=\s*"?([^"#\r\n]+)', b)
        if em:
            enc = em[1].decode('ascii', 'ignore').strip()
        try:
            s = b.decode(enc).lstrip('\ufeff')
        except (LookupError, UnicodeError):
            s = b.decode('utf-8', 'replace').lstrip('\ufeff')
        self.parse(s, filename, depth)

    def parse(self, s, filename='-', depth=0):
        self.config_name = filename
        pending = ''
        # Folding a continuation retains the physical starting line for diagnostics.
        physical = s.splitlines(keepends=True)
        logical = []
        i = 0
        while i < len(physical):
            line = i+1
            v = physical[i].rstrip('\r\n')
            i += 1
            while v.endswith('\\') and i < len(physical):
                v = v[:-1] + ' ' + physical[i].rstrip('\r\n')
                i += 1
            logical.append((line,v))
        for line,v in logical:
            if v.lstrip().startswith('##'):
                pending += v[v.index('##'):] + '\n'
                continue
            v = remove_comment(v).strip()
            if not v:
                continue
            m = re.match(r'(@?\w+)(\s*\+?=)\s*(.*)$', v)
            if not m:
                for t in re.findall(r'\w+|\S', v):
                    if re.match(r'\w', t):
                        self.warning("ignoring unknown tag '%s' at line %d, file %s" % (t,line,filename))
                    else:
                        self.warning("ignoring unknown character '%s' at line %d, file %s" % (t,line,filename))
                continue
            name,op,raw = m.groups()
            if name.startswith('@') and name not in ('@INCLUDE_PATH','@INCLUDE'):
                self.warning("ignoring unknown character '@' at line %d, file %s" % (line,filename))
                name = name[1:]
            if name == '@INCLUDE_PATH':
                paths = [self.expand(x) for x,q in tokens(raw)[0]]
                if '+' in op:
                    self.include_paths.extend(paths)
                else:
                    self.include_paths = paths
                continue
            if name == '@INCLUDE':
                inc = self.expand(scalar(raw)[0])
                choices = [Path(inc)] + [Path(p)/inc for p in self.include_paths]
                found = next((str(p) for p in choices if p.is_file()), None)
                if found is None:
                    raise ConfigError('error: @INCLUDE = %s: not found!\nExiting...\n' % inc)
                self.parse_file(found,depth+1)
                continue
            if name not in META:
                if name in OBSOLETE:
                    self.warning("Tag '%s' at line %d of file '%s' has become obsolete.\n         To avoid this warning please remove this line from your configuration file or upgrade it using \"doxygen -u\"" % (name,line,filename))
                    self.old[name] = scalar(raw)[0]
                else:
                    self.warning("ignoring unsupported tag '%s' at line %d, file %s" % (name,line,filename))
                continue
            if '+' in op and META[name]['type'] != 'stringlist':
                self.warning("operator += not supported for '%s%s'. Ignoring line at line %d, file %s" % (name,op,line,filename))
                continue
            if META[name]['type'] == 'stringlist':
                val, bad = tokens(raw)
                if bad:
                    self.warning("Invalid value for '%s' tag at line %d, file %s: Values in list '%s' are not properly space or comma separated" % (name,line,filename,raw))
                if '+' in op:
                    self.values[name].extend(val)
                else:
                    self.values[name] = val
            else:
                val,bad = scalar(raw)
                if bad:
                    self.warning("Invalid value for '%s' tag at line %d, file %s: Value '%s' is not properly quoted" % (name,line,filename,raw))
                self.values[name] = val
            self.seen.add(name)
            if pending:
                self.comments[name] = self.comments.get(name, '') + pending
                pending = ''
        self.trailing += pending

    @staticmethod
    def expand(s):
        for _ in range(20):
            t = re.sub(r'\$\(([^)]+)\)',lambda m:os.environ.get(m[1], ''), s)
            if t == s:
                return t
            s = t
        return s

    def migrate(self):
        old = self.old
        if 'DOT_FONTNAME' in old or 'DOT_FONTSIZE' in old:
            name = old.get('DOT_FONTNAME','Helvetica')
            size = old.get('DOT_FONTSIZE','10')
            if name or size:
                self.values['DOT_COMMON_ATTR'] = 'fontname=%s,fontsize=%s' % (name,size)
                self.values['DOT_EDGE_ATTR'] = 'labelfontname=%s,labelfontsize=%s' % (name,size)
        if 'HTML_TIMESTAMP' in old and old['HTML_TIMESTAMP'].lower() in ('yes','true','1'):
            self.values['TIMESTAMP'] = 'YES'
        if 'CLASS_DIAGRAMS' in old:
            self.values['CLASS_GRAPH'] = old['CLASS_DIAGRAMS']
        if 'MSCGEN_PATH' in old:
            self.values['MSCGEN_TOOL'] = old['MSCGEN_PATH']

    def validate(self, noenv=False):
        self.migrate()
        for name in ORDER:
            info = META[name]
            v = self.values[name]
            if info['type'] == 'stringlist':
                if not noenv:
                    new = []
                    for value,q in v:
                        expanded = self.expand(value)
                        if expanded:
                            if q:
                                new.append((expanded,False))
                            else:
                                new += tokens(expanded)[0]
                    self.values[name] = [(x,False) for x,q in new]
                continue
            if not noenv:
