def write_file(name, content, backup=False, strict=False):
    try:
        if name=='-':
            sys.stdout.buffer.write(content if isinstance(content,bytes) else content.encode())
            return True
        if backup and os.path.exists(name):
            os.replace(name,name+'.bak')
        Path(name).write_bytes(content if isinstance(content,bytes) else content.encode())
        return True
    except OSError:
        if strict:
            fail('Cannot open file %s for writing' % name)
        return False


