"""Command dispatch and file-oriented template operations."""
import os
import sys
from pathlib import Path
from resources import data, text, VERSION_FULL
from configuration import Configuration, ConfigError


def help_text():
    return text('help.txt').replace('./executable',sys.argv[0])


def fail(s,help=False):
    sys.stderr.write('error: '+s+'\n')
    if help:
        sys.stdout.write(help_text())
    return 1


def write_file(name, content, backup=False, strict=False):
    try:
        if name=='-':
            sys.stdout.buffer.write(content if isinstance(content,bytes) else content.encode())
            return True
        if backup and os.path.exists(name):
            os.replace(name,name+'.bak')
        Path(name).write_bytes(content if isinstance(content,bytes) else content.encode())
        return True
    except OSError:
        if strict:
            fail('Cannot open file %s for writing' % name)
        return False


def style(args):
    if not args:
        return fail('option "-w" is missing format specifier rtf, html or latex')
    fmt=args[0].lower()
    if fmt not in ('rtf','html','latex'):
        return fail('Illegal format specifier "%s": should be one of rtf, html or latex' % args[0])
    if fmt=='rtf':
        if len(args)<2:
            return fail('option "-w rtf" is missing a style sheet file name')
        write_file(args[1], data('rtf-style.txt'))
        return 0
    if len(args)<4:
        return fail('option "-w %s" does not have enough arguments' % fmt)
    conf=Configuration()
    if len(args)>4:
        conf.parse_file(args[4])
        conf.validate()
        from generation import validate_settings
        validate_settings(conf, style=True)
    if fmt=='html':
        from styles import stylesheet
        values=[data('header.html'),data('footer.html'),stylesheet(conf)]
    else:
        values=[data('header.tex'),data('footer.tex'),data('style.sty')]
    for name,content in zip(args[1:4],values):
        write_file(name,content)
    return 0


