"""XML and tag-file serializers for the declaration model."""
from resources import data, VERSION, REVISION
from configuration import ORDER,META,quote
from markup import xml,doc_xml,Doc
from model import filename_id
import re


def header(root,schema,lang):
    return "<?xml version='1.0' encoding='UTF-8' standalone='no'?>\n<%s xmlns:xsi=\"http://www.w3.org/2001/XMLSchema-instance\" xsi:noNamespaceSchemaLocation=\"%s\" version=\"%s\" xml:lang=\"%s\">\n"%(root,schema,VERSION,lang)

def yn(b):return 'yes' if b else 'no'


def sections(c):
    isclass=c.kind in ('class','struct','union','interface')
    groups={}
    for m in c.members:
        if isclass:
            kind=m.prot+'-'+('static-' if m.static and m.kind in ('variable','function') else '')+{'function':'func','variable':'attrib','typedef':'type','enum':'type','define':'type'}.get(m.kind,m.kind)
        else:kind={'function':'func','variable':'var'}.get(m.kind,m.kind)
        groups.setdefault(kind,[]).append(m)
    if isclass:
        order=[p+'-'+s for s in ['type','attrib','static-attrib'] for p in ['public','protected','package','private']]
        order += [p+'-'+s for s in ['func','static-func'] for p in ['public','protected','package','private']]
    else:order=['define','prototype','enum','typedef','func','var']
    return [(g,groups[g]) for g in order if g in groups]


def xml_config(conf,lang):
    s=header('doxyfile','doxyfile.xsd',lang)
    for name in ORDER:
        info=META[name];t=info['type'];v=conf.values[name]
        s+="  <option  id='%s' default='%s' type='%s'>" % (name,yn(not conf.different(name)),t)
        if t=='stringlist':
            s+='\n'
            for x,q in v:s+='    <value><![CDATA['+quote(x)+']]></value>\n'
            s+='  </option>\n'
        elif t=='bool':s+='<value>'+('YES' if conf.boolean(name) else 'NO')+'</value></option>\n'
        elif t=='int':s+='<value>'+str(conf.number(name))+'</value></option>\n'
        elif 'enum' in info:s+='<value>'+xml(v)+'</value></option>\n'
        else:s+='<value><![CDATA['+quote(v)+']]></value></option>\n'
    return s+'</doxyfile>\n'


def member_xml(m):
    s='      <memberdef kind="'+m.kind+'" id="'+m.refid+'" prot="'+m.prot+'" static="'+yn(m.static)+'"'
    if m.kind=='variable':s+=' mutable="'+yn(m.mutable)+'"'
    if m.kind=='function':s+=' const="'+yn(m.const)+'" explicit="'+yn(m.explicit)+'" inline="'+yn(m.inline)+'" virt="'+m.virt+'"'
    if m.kind=='enum':s+=' strong="'+yn(getattr(m,'strong',False))+'"'
    s+='>\n'
    if m.kind!='define':s+='        <type>'+xml(m.type)+'</type>\n'
    if m.kind not in ('define','enum'):
        s+='        <definition>'+xml(m.definition)+'</definition>\n        <argsstring>'+xml(m.args)+'</argsstring>\n'
    s+='        <name>'+xml(m.name)+'</name>\n'
    if m.owner.kind!='file' and m.kind!='define':s+='        <qualifiedname>'+xml(m.qualified)+'</qualifiedname>\n'
    if m.kind=='function':
        for typ,name,default in m.params:
            s+='        <param>\n          <type>'+xml(typ)+'</type>\n'
            if name:s+='          <declname>'+xml(name)+'</declname>\n'
            if default:s+='          <defval>'+xml(default)+'</defval>\n'
            s+='        </param>\n'
    if m.kind=='define':
        for typ,name,default in m.params:s+='        <param><defname>'+xml(name)+'</defname></param>\n'
    if m.initializer:s+='        <initializer>'+xml(m.initializer)+'</initializer>\n'
    for v in m.enumvalues:
        s+='        <enumvalue id="'+v.refid+'" prot="public">\n          <name>'+xml(v.name)+'</name>\n'
        if v.initializer:s+='          <initializer>'+xml(v.initializer)+'</initializer>\n'
        s+=doc_xml(v.doc,'          ')+'        </enumvalue>\n'
    s+=doc_xml(m.doc,'        ')
    s+='        <inbodydescription>\n        </inbodydescription>\n'
    loc=' file="'+xml(m.file.path)+'" line="'+str(m.line)+'" column="'+str(m.column)+'"'
    if m.body:
        loc+=' bodyfile="'+xml(m.file.path)+'" bodystart="'+str(m.body)+'" bodyend="'+str(m.end)+'"'
    elif m.kind=='function' and m.owner.kind in ('file','namespace'):
        loc+=' declfile="'+xml(m.file.path)+'" declline="'+str(m.line)+'" declcolumn="'+str(m.column)+'"'
    s+='        <location'+loc+'/>\n      </memberdef>\n'
    return s


def listing(project,f):
    conf=project.conf
    lines=f.source.splitlines()
    code=f.source_clean.splitlines()
    skip=set()
    if conf.boolean('STRIP_CODE_COMMENTS'):
        for a,b,d,t in f.comments:
            first=f.source.count('\n',0,a)+1;last=f.source.count('\n',0,b)+1
            skip.update(range(first,last+1))
    entries={};links={}
