        if c.file==f:
            entries[c.line]=(c.refid,'compound');links[c.name.split('::')[-1]]=(c.refid,'compound')
    for owner in project.files+project.classes+project.namespaces:
        for m in owner.members:
            if m.file==f:
                entries[m.line]=(m.refid,'member');links[m.name]=(m.refid,'member')
    types=set('int char float double void bool short long unsigned signed wchar_t size_t auto'.split())
    keywords=set('class struct union enum namespace public private protected const static inline virtual return if else for while switch break continue new delete typedef using template typename throw try catch nullptr constexpr'.split())
    def esc(s):return xml(s).replace(' ','<sp/>').replace('\t','<sp/>'*conf.number('TAB_SIZE'))
    s='    <programlisting>\n'
    for line_no,line in enumerate(lines,1):
        if line_no in skip:
            raw=(code[line_no-1] if line_no<=len(code) else '').rstrip()
            if not raw.strip() and line_no!=1:continue
            if not raw.strip():line=''
            else:line=raw
        extra=''
        if line_no in entries:
            ref,kind=entries[line_no];extra=' refid="'+ref+'" refkind="'+kind+'"'
        s+='<codeline lineno="'+str(line_no)+'"'+extra+'><highlight class="normal">'
        if line.lstrip().startswith('#'):
            white=line[:len(line)-len(line.lstrip())]
            s+=esc(white)+'</highlight><highlight class="preprocessor">'+esc(line.lstrip())+'</highlight>'
            if line.lstrip().startswith('#define'):
                s+='<highlight class="preprocessor"></highlight><highlight class="normal"></highlight>'
            elif not line.lstrip().startswith('#endif'):s+='<highlight class="normal"></highlight>'
        else:
            pos=0
            for m in re.finditer(r'\b\w+\b|"(?:\\.|[^"\\])*"|//.*',line):
                s+=esc(line[pos:m.start()]);word=m[0]
                kind='keywordtype' if word in types else 'keyword' if word in keywords else 'stringliteral' if word.startswith('"') else 'comment' if word.startswith('//') else ''
                end=m.end()
                if word in ('class','struct','namespace','enum'):
                    while end<len(line) and line[end]==' ':end+=1
                    word=line[m.start():end]
                if kind:s+='</highlight><highlight class="'+kind+'">'+esc(word)+'</highlight><highlight class="normal">'
                elif word in links:
                    ref,k=links[word];s+='<ref refid="'+ref+'" kindref="'+k+'">'+xml(word)+'</ref>'
                else:s+=esc(word)
