    s=header('doxyfile','doxyfile.xsd',lang)
    for name in ORDER:
        info=META[name];t=info['type'];v=conf.values[name]
        s+="  <option  id='%s' default='%s' type='%s'>" % (name,yn(not conf.different(name)),t)
        if t=='stringlist':
            s+='\n'
            for x,q in v:s+='    <value><![CDATA['+quote(x)+']]></value>\n'
            s+='  </option>\n'
        elif t=='bool':s+='<value>'+('YES' if conf.boolean(name) else 'NO')+'</value></option>\n'
        elif t=='int':s+='<value>'+str(conf.number(name))+'</value></option>\n'
        elif 'enum' in info:s+='<value>'+xml(v)+'</value></option>\n'
        else:s+='<value><![CDATA['+quote(v)+']]></value></option>\n'
    return s+'</doxyfile>\n'


