        if mode=='FAIL_ON_WARNINGS_PRINT' and self.out is sys.stderr:self.saved+=s
        else:self.out.write(s)
        if mode=='YES':raise ConfigError('')
    def close(self):
        if self.saved:sys.stderr.write(self.saved)
        if self.out not in (sys.stderr,sys.stdout):self.out.close()
