    excluded=[str(Path(x).absolute()) for x in c.get('EXCLUDE')]
    epattern=c.get('EXCLUDE_PATTERNS')
    out=[]
    def excluded_path(p):
        absolute=str(p.absolute())
        return any(absolute==e or absolute.startswith(e.rstrip('/')+'/') for e in excluded) or any(fnmatch.fnmatch(absolute,e) or fnmatch.fnmatch(p.name,e) or fnmatch.fnmatch(str(p),e) for e in epattern)
