        for line in searchlog:info(line)
        if not files:
            warn.emit('No files to be processed, please check your settings, in particular INPUT, FILE_PATTERNS, and RECURSIVE')
        info('Reading and parsing tag files')
        for tag in c.get('TAGFILES'):
            name=tag.split('=')[0]
            if not Path(name).is_file():sys.stderr.write("error: tag file '%s' does not exist or is not a file. Skipping it...\n"%name)
        info('Parsing files')
        project=Project(c)
        for f in files:
            if not f.endswith(('.md','.markdown','.py')):info('Preprocessing '+f+'...')
            info('Parsing file '+f+'...')
            project.scan(f)
        project.finish()
