                        if m.prot=='private' and not c.boolean('EXTRACT_PRIVATE'):continue
                        if m.static and owner.kind in ('file','namespace') and not c.boolean('EXTRACT_STATIC'):continue
                        kinds={'define':'macro definition','typedef':'typedef','enum':'enumeration','function':'function','variable':'variable'}
                        desc=m.name+(m.args if m.kind=='function' else '')
