                if project.files and line.startswith('type '):
                    names=set(m.type for owner in project.files+project.classes+project.namespaces for m in owner.members if m.type)
                    n=len(names)+len(project.classes)+len([m for owner in project.classes for m in owner.members])
                    line=f'type lookup cache used {n}/65536 hits=0 misses={n}'
                elif project.files and line.startswith('symbol '):
                    n=sum(len(x.members) for x in project.files+project.classes+project.namespaces)+len(project.files)+len(project.classes)+3
                    line=f'symbol lookup cache used {n}/65536 hits={n+5} misses={n}'
            if line=='finalizing index lists...' and (c.boolean('GENERATE_HTML') or c.boolean('GENERATE_LATEX')):
                for l in ['index page','page index','topic index','module index','module member index','namespace index','namespace member index','concept index','annotated compound index','alphabetical compound index','hierarchical class index','member index','file index','file member index','example index']:
