def generate_navigation(project,directory,title,classes,namespaces,files,ext):
    c=project.conf
    nodes=[]
    def members(label,page,ms):
        child=[['All',page+ext,None]]
        for k,suffix,lab in [('function','func','Functions'),('variable','vars','Variables'),('typedef','type','Typedefs'),('enum','enum','Enumerations'),('define','defs','Macros')]:
            if any(m.kind==k for m in ms):child.append([lab,page+'_'+suffix+ext,None])
        return [label,page+ext,child]
    if namespaces:nodes.append(['Namespaces','namespaces'+ext,[['Namespace List','namespaces'+ext,'namespaces_dup']]])
    if classes:
        child=[['Class List','annotated'+ext,'annotated_dup']]
        if c.boolean('ALPHABETICAL_INDEX'):child.append(['Class Index','classes'+ext,None])
        ms=[m for cl in classes for m in cl.members if visible(m,c)]
        if ms:child.append(members('Class Members','functions',ms))
        nodes.append(['Classes','annotated'+ext,child])
    if files:
        child=[['File List','files'+ext,'files_dup']]
        ms=[m for f in files for m in f.members if visible(m,c)]
        if ms:child.append(members('File Members','globals',ms))
        nodes.append(['Files','files'+ext,child])
    if not nodes:return
    def menu(node):
        label,url,child=node
        s='{text:"'+label+'",url:"'+url+'"'
        if isinstance(child,list):s+=',children:[\n'+',\n'.join(menu(x) for x in child)+']'
        return s+'}'
    if (directory/'menudata.js').exists():
        license=text('html/menudata.js').split('var menudata=')[0]
        (directory/'menudata.js').write_text(license+'var menudata={children:[\n'+',\n'.join(menu(x) for x in [['Main Page','index'+ext,None]]+nodes)+']}\n')
    if not c.boolean('GENERATE_TREEVIEW'):return
    def nav(node,indent):
        label,url,child=node
        s=' '*indent+'[ "'+label.replace('"','\\"')+'", "'+url+'", '
        if child is None:s+='null'
        elif isinstance(child,str):s+='"'+child+'"'
        else:s+='[\n'+',\n'.join(nav(x,indent+2) for x in child)+'\n'+' '*indent+']'
        return s+' ]'
    positions={'index'+ext:[],'pages'+ext:[]}
