    tail=text('html/navtreedata.js').split('const SYNCONMSG')[1]
    (directory/'navtreedata.js').write_text(license+'var NAVTREE =\n[\n'+nav([title,'index'+ext,nodes],2)+'\n];\n\nvar NAVTREEINDEX =\n[\n"'+keys[0]+'"\n];\n\nconst SYNCONMSG'+tail)
